-- NEW-MIS-002: immutable Customer Acceptance evidence and bounded customer links.
do $migration$ begin if to_regclass('storage.buckets')is not null then execute $storage$insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('customer-acceptance-evidence','customer-acceptance-evidence',false,3145728,array['image/jpeg','image/png','image/webp','application/pdf'])on conflict(id)do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types$storage$;end if;end$migration$;

create table public.customer_acceptance_states(id uuid primary key default gen_random_uuid(),code text unique not null,display_name text not null,description text not null,version integer not null default 1,display_order integer not null,is_active boolean not null default true);
create table public.customer_acceptance_methods(id uuid primary key default gen_random_uuid(),code text unique not null,display_name text not null,description text not null,version integer not null default 1,display_order integer not null,is_active boolean not null default true);
insert into public.customer_acceptance_states(code,display_name,description,display_order)values('ACCEPTED','Accepted','Customer accepted the completed work.',10),('ACCEPTED_WITH_COMMENTS','Accepted with comments','Customer accepted the completed work and supplied comments.',20),('DISPUTED','Disputed','Customer disputed some or all completed work.',30),('DECLINED','Declined','Customer declined to accept the completed work.',40);
insert into public.customer_acceptance_methods(code,display_name,description,display_order)values('PHONE','Phone','Acknowledgement received by telephone.',10),('VERBAL','Verbal','Acknowledgement received verbally.',20),('IN_PERSON','In person','Acknowledgement received in person.',30),('WRITTEN','Written','Acknowledgement received in writing.',40),('EMAIL','Email','Acknowledgement received by email.',50),('SECURE_LINK','Secure link','Customer submitted through a bounded secure link.',60),('PORTAL','Customer portal','Customer submitted through an authenticated portal.',70),('OTHER','Other','Another recorded acknowledgement method.',80);

create table public.customer_acceptance_records(
 id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),operating_location_id uuid not null references public.operating_locations(id),mission_id uuid not null references public.missions(id),completion_revision_id uuid not null references public.mission_completion_revisions(id),sequence_number integer not null,
 state_id uuid not null references public.customer_acceptance_states(id),state_snapshot jsonb not null,method_id uuid not null references public.customer_acceptance_methods(id),method_snapshot jsonb not null,submission_channel text not null check(submission_channel in('OPERATOR','SECURE_LINK','PORTAL')),
 customer_id uuid not null references public.clients(id),customer_snapshot jsonb not null,customer_contact_name text not null,customer_contact_role text,customer_contact_email text,customer_contact_phone text,customer_comments text,acknowledged_at timestamptz not null,
 consent_declaration text,consented_at timestamptz,signature_file_id uuid,operator_personnel_id uuid references public.personnel(id),operator_personnel_snapshot jsonb,secure_link_id uuid,authenticated_portal_identity_id uuid,supersedes_acceptance_id uuid references public.customer_acceptance_records(id),created_by_internal_user_id uuid references public.internal_users(id),created_at timestamptz not null default now(),
 unique(organisation_id,mission_id,sequence_number),check(submission_channel='OPERATOR'or(consent_declaration is not null and consented_at is not null and signature_file_id is not null))
);
create table public.customer_acceptance_files(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),mission_id uuid not null references public.missions(id),acceptance_id uuid references public.customer_acceptance_records(id),internal_file_id uuid not null,immutable_file_version integer not null default 1,kind text not null check(kind in('SIGNATURE','ATTACHMENT')),original_filename text not null,content_type text not null,byte_size integer not null check(byte_size>0 and byte_size<=3145728),sha256_checksum text not null,storage_provider text not null,storage_bucket text not null,provider_key text not null,provenance jsonb not null,uploaded_by_internal_user_id uuid references public.internal_users(id),upload_token_hash text,created_at timestamptz not null default now(),claimed_at timestamptz,unique(organisation_id,internal_file_id,immutable_file_version));
create table public.customer_acceptance_links(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),operating_location_id uuid not null references public.operating_locations(id),mission_id uuid not null references public.missions(id),completion_revision_id uuid not null references public.mission_completion_revisions(id),customer_id uuid not null references public.clients(id),customer_snapshot jsonb not null,intended_contact_name text not null,intended_contact_email text,token_hash text unique not null,issued_by_personnel_id uuid not null references public.personnel(id),issued_at timestamptz not null default now(),expires_at timestamptz not null,revoked_at timestamptz,revoked_by_personnel_id uuid references public.personnel(id),revocation_reason text,consumed_at timestamptz,resulting_acceptance_id uuid references public.customer_acceptance_records(id),access_count integer not null default 0,last_access_at timestamptz,row_version integer not null default 1,check(expires_at>issued_at));
alter table public.customer_acceptance_records add constraint customer_acceptance_secure_link_fk foreign key(secure_link_id)references public.customer_acceptance_links(id);

do $$declare t text;begin foreach t in array array['customer_acceptance_records','customer_acceptance_files','customer_acceptance_links']loop execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);execute format('create policy %I on public.%I for select to authenticated using(public.current_user_has_organisation_access(organisation_id))',t||'_tenant_read',t);execute format('revoke all on table public.%I from public,anon,authenticated',t);execute format('grant select,insert on table public.%I to service_role',t);end loop;foreach t in array array['customer_acceptance_records','customer_acceptance_files']loop execute format('create trigger %I before update or delete on public.%I for each row execute function public.reject_append_only_mutation()',t||'_immutable',t);end loop;end$$;

create function public.ftf_customer_acceptance_context(p_organisation_id uuid,p_mission_id uuid)returns jsonb language sql security definer set search_path=public,pg_temp as $$select jsonb_build_object('missionId',m.id,'missionReference',coalesce(j.reference,m.id::text),'completionRevisionId',c.id,'completedAt',c.completed_at,'customerId',cl.id,'customer',jsonb_build_object('id',cl.id,'name',cl.name,'contactName',cl.contact_name,'contactEmail',cl.contact_email,'contactPhone',cl.contact_phone),'organisation',jsonb_build_object('name',o.name))from public.missions m join public.jobs j on j.organisation_id=m.organisation_id and j.id=m.job_id join public.clients cl on cl.organisation_id=j.organisation_id and cl.id=j.client_id join public.organisations o on o.id=m.organisation_id join lateral(select x.*from public.mission_completion_revisions x where x.organisation_id=m.organisation_id and x.mission_id=m.id order by x.version_number desc limit 1)c on true where m.organisation_id=p_organisation_id and m.id=p_mission_id and m.archived_at is null$$;
create function public.ftf_read_customer_acceptance(p_organisation_id uuid,p_mission_id uuid)returns jsonb language sql security definer set search_path=public,pg_temp as $$select jsonb_build_object('context',public.ftf_customer_acceptance_context(p_organisation_id,p_mission_id),'records',coalesce((select jsonb_agg(to_jsonb(r)order by r.sequence_number)from public.customer_acceptance_records r where r.organisation_id=p_organisation_id and r.mission_id=p_mission_id),'[]'),'links',coalesce((select jsonb_agg(to_jsonb(l)-'token_hash'order by l.issued_at desc)from public.customer_acceptance_links l where l.organisation_id=p_organisation_id and l.mission_id=p_mission_id),'[]'),'catalogues',jsonb_build_object('states',(select jsonb_agg(to_jsonb(s)order by s.display_order)from public.customer_acceptance_states s where s.is_active),'methods',(select jsonb_agg(to_jsonb(m)order by m.display_order)from public.customer_acceptance_methods m where m.is_active)))$$;

create function public.ftf_create_customer_acceptance(p_organisation_id uuid,p_actor_internal_user_id uuid,p_mission_id uuid,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare m public.missions%rowtype;c public.mission_completion_revisions%rowtype;j public.jobs%rowtype;cl public.clients%rowtype;p public.personnel%rowtype;s public.customer_acceptance_states%rowtype;md public.customer_acceptance_methods%rowtype;r public.customer_acceptance_records%rowtype;n integer;begin select*into m from public.missions where organisation_id=p_organisation_id and id=p_mission_id and archived_at is null;select*into c from public.mission_completion_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id order by version_number desc limit 1;if c.id is null then return jsonb_build_object('completion_required',true);end if;select*into j from public.jobs where organisation_id=p_organisation_id and id=m.job_id;select*into cl from public.clients where organisation_id=p_organisation_id and id=j.client_id;select*into p from public.personnel where organisation_id=p_organisation_id and internal_user_id=p_actor_internal_user_id and archived_at is null;select*into s from public.customer_acceptance_states where code=p_payload->>'stateCode'and is_active;select*into md from public.customer_acceptance_methods where code=p_payload->>'methodCode'and is_active;if p.id is null or s.id is null or md.id is null then return jsonb_build_object('validation_error',true);end if;if md.code in('PHONE','VERBAL')and length(trim(coalesce(p_payload->>'comments','')))=0 then return jsonb_build_object('validation_error',true);end if;select coalesce(max(sequence_number),0)+1 into n from public.customer_acceptance_records where organisation_id=p_organisation_id and mission_id=p_mission_id;insert into public.customer_acceptance_records(organisation_id,operating_location_id,mission_id,completion_revision_id,sequence_number,state_id,state_snapshot,method_id,method_snapshot,submission_channel,customer_id,customer_snapshot,customer_contact_name,customer_contact_role,customer_contact_email,customer_contact_phone,customer_comments,acknowledged_at,operator_personnel_id,operator_personnel_snapshot,supersedes_acceptance_id,created_by_internal_user_id)values(p_organisation_id,m.operating_location_id,m.id,c.id,n,s.id,to_jsonb(s),md.id,to_jsonb(md),'OPERATOR',cl.id,to_jsonb(cl)-'organisation_id',trim(p_payload->>'customerContactName'),p_payload->>'customerContactRole',p_payload->>'customerContactEmail',p_payload->>'customerContactPhone',p_payload->>'comments',(p_payload->>'acknowledgedAt')::timestamptz,p.id,jsonb_build_object('id',p.id,'name',p.full_name),nullif(p_payload->>'supersedesAcceptanceId','')::uuid,p_actor_internal_user_id)returning*into r;insert into public.audit_events(organisation_id,actor_internal_user_id,event_type,entity_type,entity_id,event_payload)values(p_organisation_id,p_actor_internal_user_id,'customer_acceptance.recorded','customer_acceptance',r.id,jsonb_build_object('mission_id',m.id));insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(p_organisation_id,'post_mission.customer_acceptance.recorded','mission',m.id,jsonb_build_object('acceptance_id',r.id));return jsonb_build_object('record',to_jsonb(r));end$$;

create function public.ftf_issue_customer_acceptance_link(p_organisation_id uuid,p_actor_internal_user_id uuid,p_mission_id uuid,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare m public.missions%rowtype;c public.mission_completion_revisions%rowtype;j public.jobs%rowtype;cl public.clients%rowtype;p public.personnel%rowtype;r public.customer_acceptance_links%rowtype;begin select*into m from public.missions where organisation_id=p_organisation_id and id=p_mission_id and archived_at is null;select*into c from public.mission_completion_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id order by version_number desc limit 1;if c.id is null then return jsonb_build_object('completion_required',true);end if;select*into j from public.jobs where organisation_id=p_organisation_id and id=m.job_id;select*into cl from public.clients where organisation_id=p_organisation_id and id=j.client_id;select*into p from public.personnel where organisation_id=p_organisation_id and internal_user_id=p_actor_internal_user_id and archived_at is null;if p.id is null then return jsonb_build_object('validation_error',true);end if;insert into public.customer_acceptance_links(organisation_id,operating_location_id,mission_id,completion_revision_id,customer_id,customer_snapshot,intended_contact_name,intended_contact_email,token_hash,issued_by_personnel_id,expires_at)values(p_organisation_id,m.operating_location_id,m.id,c.id,cl.id,to_jsonb(cl)-'organisation_id',trim(p_payload->>'contactName'),p_payload->>'contactEmail',p_payload->>'tokenHash',p.id,now()+make_interval(hours=>least(greatest(coalesce((p_payload->>'expiresInHours')::integer,48),1),168)))returning*into r;insert into public.audit_events(organisation_id,actor_internal_user_id,event_type,entity_type,entity_id,event_payload)values(p_organisation_id,p_actor_internal_user_id,'customer_acceptance.link_issued','customer_acceptance_link',r.id,jsonb_build_object('mission_id',m.id,'expires_at',r.expires_at));insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(p_organisation_id,'post_mission.customer_acceptance.link_issued','mission',m.id,jsonb_build_object('link_id',r.id));return jsonb_build_object('record',to_jsonb(r)-'token_hash');end$$;
create function public.ftf_revoke_customer_acceptance_link(p_organisation_id uuid,p_actor_internal_user_id uuid,p_mission_id uuid,p_link_id uuid,p_expected_version integer,p_reason text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare p public.personnel%rowtype;r public.customer_acceptance_links%rowtype;begin select*into p from public.personnel where organisation_id=p_organisation_id and internal_user_id=p_actor_internal_user_id and archived_at is null;update public.customer_acceptance_links set revoked_at=now(),revoked_by_personnel_id=p.id,revocation_reason=trim(p_reason),row_version=row_version+1 where organisation_id=p_organisation_id and mission_id=p_mission_id and id=p_link_id and row_version=p_expected_version and revoked_at is null and consumed_at is null returning*into r;if r.id is null then return jsonb_build_object('conflict',true);end if;insert into public.audit_events(organisation_id,actor_internal_user_id,event_type,entity_type,entity_id,event_payload)values(p_organisation_id,p_actor_internal_user_id,'customer_acceptance.link_revoked','customer_acceptance_link',r.id,jsonb_build_object('reason',p_reason));insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(p_organisation_id,'post_mission.customer_acceptance.link_revoked','mission',p_mission_id,jsonb_build_object('link_id',r.id));return jsonb_build_object('record',to_jsonb(r)-'token_hash');end$$;

create function public.ftf_resolve_customer_acceptance_link(p_token_hash text,p_access_fingerprint text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare l public.customer_acceptance_links%rowtype;ctx jsonb;begin select*into l from public.customer_acceptance_links where token_hash=p_token_hash for update;if l.id is null then return jsonb_build_object('invalid',true);end if;if l.revoked_at is not null then return jsonb_build_object('revoked',true);end if;if l.consumed_at is not null then return jsonb_build_object('consumed',true);end if;if l.expires_at<=now()then return jsonb_build_object('expired',true);end if;if l.access_count>=50 then return jsonb_build_object('rate_limited',true);end if;update public.customer_acceptance_links set access_count=access_count+1,last_access_at=now()where id=l.id;ctx=public.ftf_customer_acceptance_context(l.organisation_id,l.mission_id);return jsonb_build_object('linkId',l.id,'organisationId',l.organisation_id,'missionId',l.mission_id,'rowVersion',l.row_version,'expiresAt',l.expires_at,'organisationName',ctx#>>'{organisation,name}','missionReference',ctx->>'missionReference','completedAt',ctx->>'completedAt','customerName',l.customer_snapshot->>'name','intendedContactName',l.intended_contact_name,'states',(select jsonb_agg(jsonb_build_object('code',s.code,'displayName',s.display_name,'description',s.description)order by s.display_order)from public.customer_acceptance_states s where s.is_active));end$$;
create function public.ftf_submit_customer_acceptance_link(p_token_hash text,p_access_fingerprint text,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare l public.customer_acceptance_links%rowtype;s public.customer_acceptance_states%rowtype;md public.customer_acceptance_methods%rowtype;r public.customer_acceptance_records%rowtype;n integer;begin select*into l from public.customer_acceptance_links where token_hash=p_token_hash for update;if l.id is null or l.revoked_at is not null or l.expires_at<=now()or l.consumed_at is not null then return jsonb_build_object('unavailable',true);end if;if coalesce((p_payload->>'consent')::boolean,false)is not true or length(trim(coalesce(p_payload->>'consentDeclaration','')))<10 or nullif(p_payload->>'signatureFileId','')is null then return jsonb_build_object('validation_error',true);end if;select*into s from public.customer_acceptance_states where code=p_payload->>'stateCode'and is_active;select*into md from public.customer_acceptance_methods where code='SECURE_LINK';select coalesce(max(sequence_number),0)+1 into n from public.customer_acceptance_records where organisation_id=l.organisation_id and mission_id=l.mission_id;insert into public.customer_acceptance_records(organisation_id,operating_location_id,mission_id,completion_revision_id,sequence_number,state_id,state_snapshot,method_id,method_snapshot,submission_channel,customer_id,customer_snapshot,customer_contact_name,customer_contact_role,customer_contact_email,customer_comments,acknowledged_at,consent_declaration,consented_at,signature_file_id,secure_link_id)values(l.organisation_id,l.operating_location_id,l.mission_id,l.completion_revision_id,n,s.id,to_jsonb(s),md.id,to_jsonb(md),'SECURE_LINK',l.customer_id,l.customer_snapshot,trim(p_payload->>'customerContactName'),p_payload->>'customerContactRole',p_payload->>'customerContactEmail',p_payload->>'comments',now(),p_payload->>'consentDeclaration',now(),(p_payload->>'signatureFileId')::uuid,l.id)returning*into r;update public.customer_acceptance_files set acceptance_id=r.id,claimed_at=now()where organisation_id=l.organisation_id and internal_file_id=r.signature_file_id and kind='SIGNATURE'and upload_token_hash=p_token_hash and claimed_at is null;if not found then raise exception'Invalid signature evidence';end if;update public.customer_acceptance_links set consumed_at=now(),resulting_acceptance_id=r.id,row_version=row_version+1 where id=l.id;insert into public.audit_events(organisation_id,event_type,entity_type,entity_id,event_payload)values(l.organisation_id,'customer_acceptance.customer_submitted','customer_acceptance',r.id,jsonb_build_object('mission_id',l.mission_id,'link_id',l.id));insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(l.organisation_id,'post_mission.customer_acceptance.customer_submitted','mission',l.mission_id,jsonb_build_object('acceptance_id',r.id,'link_id',l.id));return jsonb_build_object('record',jsonb_build_object('id',r.id,'state',s.code,'acknowledgedAt',r.acknowledged_at));end$$;

insert into public.permissions(organisation_id,code,description)select o.id,v.code,v.description from public.organisations o cross join(values('mission.customer_acceptance.read','View Customer Acceptance evidence'),('mission.customer_acceptance.record','Record Customer Acceptance evidence'),('mission.customer_acceptance.link.issue','Issue customer acceptance links'),('mission.customer_acceptance.link.revoke','Revoke customer acceptance links'),('mission.customer_acceptance.attachment.upload','Upload Customer Acceptance evidence'))v(code,description)on conflict(organisation_id,code)do nothing;
insert into public.role_permissions(organisation_id,role_id,permission_id)select r.organisation_id,r.id,p.id from public.roles r join public.permissions p on p.organisation_id=r.organisation_id and p.code like'mission.customer_acceptance.%'where r.code='admin'on conflict do nothing;
create function public.ftf_provision_customer_acceptance_permissions()returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin insert into public.permissions(organisation_id,code,description)select new.organisation_id,v.code,v.description from(values('mission.customer_acceptance.read','View Customer Acceptance evidence'),('mission.customer_acceptance.record','Record Customer Acceptance evidence'),('mission.customer_acceptance.link.issue','Issue customer acceptance links'),('mission.customer_acceptance.link.revoke','Revoke customer acceptance links'),('mission.customer_acceptance.attachment.upload','Upload Customer Acceptance evidence'))v(code,description)on conflict do nothing;if new.code='admin'then insert into public.role_permissions(organisation_id,role_id,permission_id)select new.organisation_id,new.id,p.id from public.permissions p where p.organisation_id=new.organisation_id and p.code like'mission.customer_acceptance.%'on conflict do nothing;end if;return new;end$$;
create trigger provision_customer_acceptance_permissions after insert on public.roles for each row execute function public.ftf_provision_customer_acceptance_permissions();

revoke all on function public.ftf_customer_acceptance_context(uuid,uuid),public.ftf_read_customer_acceptance(uuid,uuid),public.ftf_create_customer_acceptance(uuid,uuid,uuid,jsonb),public.ftf_issue_customer_acceptance_link(uuid,uuid,uuid,jsonb),public.ftf_revoke_customer_acceptance_link(uuid,uuid,uuid,uuid,integer,text),public.ftf_resolve_customer_acceptance_link(text,text),public.ftf_submit_customer_acceptance_link(text,text,jsonb)from public,anon,authenticated;
grant execute on function public.ftf_read_customer_acceptance(uuid,uuid),public.ftf_create_customer_acceptance(uuid,uuid,uuid,jsonb),public.ftf_issue_customer_acceptance_link(uuid,uuid,uuid,jsonb),public.ftf_revoke_customer_acceptance_link(uuid,uuid,uuid,uuid,integer,text),public.ftf_resolve_customer_acceptance_link(text,text),public.ftf_submit_customer_acceptance_link(text,text,jsonb)to service_role;
